  // Outcome columns (#29/#30): shown only when some group carries a verify
  // verdict (row.passRate); a group without one renders n/a, never 0%.
  var OUTCOME_COLS = ["passRate", "passCi", "passHatK", "anyPassAtK"];
  var LABELS = {
    experiment: "experiment", variant: "variant", workflow: "workflow", agent: "agent",
    runs: "runs", avgTotalTokens: "avg tokens", avgCostUsd: "avg cost",
    avgDurationMs: "avg duration", successRate: "success",
    passRate: "pass", passCi: "pass@1 · 95% CI", passHatK: "pass^k", anyPassAtK: "any-pass@k",
  };

